/* 학습 해설
 * 경로 문자열을 뒤에서 만드는 이유: 부모를 따라가며 앞에 붙이기
 * 파일에서 부모 디렉터리로 올라가면 이름을 report,docs,home 순서로 만납니다. 최종 문자열은 /home/docs/report이므로 매번 기존 문자열 전체를 오른쪽으로 옮기기보다 버퍼 끝에서 앞으로 채우는 편이 자연스럽습니다.
 * prepend_buffer는 현재 시작 포인터buf와 남은 길이len을 가집니다. DECLARE_BUFFER는 원래버퍼+전체길이에서 시작합니다. prepend_char는 여유가 있으면 포인터를 한 칸 낮춰 문자를 쓰고,없으면len=-1입니다. prepend는 이름 길이만큼 포인터를 낮춰 복사합니다. extract_string은len이 음수면 ENAMETOOLONG 오류 포인터,그렇지 않으면현재buf를 반환합니다.
 * 8바이트 버퍼에서 먼저 NUL을 넣으면 위치7,이름ab를 넣으면위치5,슬래시를 넣으면위치4입니다. 결과는원래버퍼+4의 /ab와NUL,총4바이트입니다. 호출자가원래버퍼주소를출력하면이문자열의시작을놓칠수있으므로반환된포인터를사용해야합니다.
 */
static bool prepend(struct prepend_buffer *p, const char *str, int namelen)
{
	// Already overflowed?
	if (p->len < 0)
		return false;

	// Will overflow?
	if (p->len < namelen) {
		// Fill as much as possible from the end of the name
		str += namelen - p->len;
		p->buf -= p->len;
		prepend_copy(p->buf, str, p->len);
		p->len = -1;
		return false;
	}

	// Fits fully
	p->len -= namelen;
	p->buf -= namelen;
	return prepend_copy(p->buf, str, namelen);
}

/**
 * prepend_name - prepend a pathname in front of current buffer pointer
 * @p: prepend buffer which contains buffer pointer and allocated length
 * @name: name string and length qstr structure
 *
 * With RCU path tracing, it may race with d_move(). Use READ_ONCE() to
 * make sure that either the old or the new name pointer and length are
 * fetched. However, there may be mismatch between length and pointer.
 * But since the length cannot be trusted, we need to copy the name very
 * carefully when doing the prepend_copy(). It also prepends "/" at
 * the beginning of the name. The sequence number check at the caller will
 * retry it again when a d_move() does happen. So any garbage in the buffer
 * due to mismatched pointer and length will be discarded.
 *
 * Load acquire is needed to make sure that we see the new name data even
 * if we might get the length wrong.
 */

/* 학습 해설
 * Rename 중 이름 복사: RCU만으로 포인터와 길이가 한 쌍이 되지는 않는다
 * 이름을바꾸는CPU와경로를읽는CPU가동시에실행되면독자는이전이름포인터와새길이를섞어읽을수있습니다. 객체수명을지키는것과여러필드를동일시점의한쌍으로읽는것은다른문제입니다.
 * prepend_name은이름포인터를smp_load_acquire로,길이는READ_ONCE로읽습니다. acquire는새이름데이터관찰순서를돕지만포인터와길이를한번에묶지는않습니다. prepend_copy는copy_from_kernel_nofault로복사하고실패하면대상영역을x로채우며false입니다. 호출자는rename sequence가변했는지확인해그시도의결과를버리고다시만듭니다.
 * 이전이름길이3인포인터와새길이20을잘못짝지으면3바이트문자열의범위를넘어읽을수있습니다. nofault복사는이런낙관적읽기실패를처리할수있게하고sequence검사는그경로를정상스냅샷으로채택하지않게합니다. x채움은사용자에게손상된경로를정답으로제시하려는기능이아닙니다.
 */
static bool prepend_name(struct prepend_buffer *p, const struct qstr *name)
{
	const char *dname = smp_load_acquire(&name->name); /* ^^^ */
	u32 dlen = READ_ONCE(name->len);

	return prepend(p, dname, dlen) && prepend_char(p, '/');
}

