 * 합성 파일 이름: 임시64바이트 버퍼와 최종 버퍼의 이중 한도
 * 소켓같은합성객체는일반디렉터리경로대신형식화한이름으로표시할수있습니다. 사용자에게줄버퍼가커도중간형식화버퍼가작으면긴이름을그대로만들수없습니다.
 * dynamic_dname은64바이트temp에vsnprintf하고반환된필요문자수에NUL용1을더해sz로삼습니다. sz가temp크기또는최종buflen보다크면ENAMETOOLONG입니다. 통과하면최종버퍼끝에서sz만큼앞에temp를복사해그주소를반환합니다. 단순히temp에잘려들어간문자수를성공길이로쓰지않습니다.
 * 문자63개이면NUL포함64라temp에맞습니다. 문자64개이면sz65라최종버퍼가1000바이트여도실패합니다. 최종버퍼20바이트에문자5개를만들면NUL포함6바이트를끝에놓아시작주소는buffer+14입니다. 항상반환포인터로문자열을읽어야합니다.
 */
char *dynamic_dname(char *buffer, int buflen, const char *fmt, ...)
{
	va_list args;
	char temp[64];
	int sz;

	va_start(args, fmt);
	sz = vsnprintf(temp, sizeof(temp), fmt, args) + 1;
	va_end(args);

	if (sz > sizeof(temp) || sz > buflen)
		return ERR_PTR(-ENAMETOOLONG);

	buffer += buflen - sz;
	return memcpy(buffer, temp, sz);
}

char *simple_dname(struct dentry *dentry, char *buffer, int buflen)
{
	DECLARE_BUFFER(b, buffer, buflen);
	/* these dentries are never renamed, so d_lock is not needed */
	prepend(&b, " (deleted)", 11);
	prepend(&b, dentry->d_name.name, dentry->d_name.len);
	prepend_char(&b, '/');
	return extract_string(&b);
}

